pub(super) fn edge_ring_is_strictly_convex(
    points: &[Point],
    edge: [usize; 2],
    ring: &[usize],
) -> bool {
    if ring.len() < 3 {
        return false;
    }

    let origin = points[edge[0]];
    let axis = vec_from(origin, points[edge[1]]);
    let axis_len = norm3(axis);
    if axis_len < 1e-14 {
        return false;
    }
    let axis = (axis.0 / axis_len, axis.1 / axis_len, axis.2 / axis_len);
    let reference = if axis.0.abs() < 0.9 {
        (1.0, 0.0, 0.0)
    } else {
        (0.0, 1.0, 0.0)
    };
    let u = cross3(axis, reference);
    let u_len = norm3(u);
    if u_len < 1e-14 {
        return false;
    }
    let u = (u.0 / u_len, u.1 / u_len, u.2 / u_len);
    let v = cross3(axis, u);

    let projected: Vec<_> = ring
        .iter()
        .map(|&idx| {
            let delta = vec_from(origin, points[idx]);
            robust::Coord {
                x: dot3(delta, u),
                y: dot3(delta, v),
            }
        })
        .collect();

    let mut area = 0.0;
    for idx in 0..projected.len() {
        let a = projected[idx];
        let b = projected[(idx + 1) % projected.len()];
        area += a.x * b.y - a.y * b.x;
    }
    if area.abs() < 1e-14 {
        return false;
    }
    let sign = area.signum();

    for idx in 0..projected.len() {
        let a = projected[idx];
        let b = projected[(idx + 1) % projected.len()];
        let c = projected[(idx + 2) % projected.len()];
        let turn = robust::orient2d(a, b, c);
        if turn.abs() < 1e-14 || turn.signum() != sign {
            return false;
        }
    }
    true
}

pub(super) fn edge_blocks_facet(points: &[Point], edge: [usize; 2], facet: [usize; 3]) -> bool {
    if facet.contains(&edge[0]) || facet.contains(&edge[1]) {
        return false;
    }

    let a = points[facet[0]];
    let b = points[facet[1]];
    let c = points[facet[2]];
    let p = points[edge[0]];
    let q = points[edge[1]];
    let sp = robust::orient3d(rc3(a), rc3(b), rc3(c), rc3(p));
    let sq = robust::orient3d(rc3(a), rc3(b), rc3(c), rc3(q));
    if sp == 0.0 && sq == 0.0 {
        return coplanar_edge_crosses_facet(p, q, a, b, c);
    }
    if sp == 0.0 {
        return point_in_triangle_3d(p, a, b, c);
    }
    if sq == 0.0 {
        return point_in_triangle_3d(q, a, b, c);
    }
    if sp.signum() == sq.signum() {
        return false;
    }

    let denom = sp - sq;
    if denom == 0.0 {
        return false;
    }
    let t = sp / denom;
    if !(0.0..=1.0).contains(&t) {
        return false;
    }
    let hit = Point::new_3d(
        p.x + (q.x - p.x) * t,
        p.y + (q.y - p.y) * t,
        p.z + (q.z - p.z) * t,
    );
    point_in_triangle_3d(hit, a, b, c)
}
